def prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

k = 0
for n in range(2532000, 2532161):
    if prime(n):
        k += 1
        print(k, n)

